options.onCreated:
const s = this.vueState
const field = this
const PERSON_FORM    = '6a37d3bd4cfbfdbe257fc912'   // PERSON (แก้ไข)
const INSURANCE_FORM = '6a467fb539179670f85ba29e'   // PERSON INSURANCE
const VISIT_FORM     = '6a40fdec4b6dfdf45acbfbce'    // Visit
const CHECK_PROC     = '6a4ccaef49285083acfeb081'   // แก้เป็น id จริง

const getPid = () => field.formModel && field.formModel.pid

// merge เฉพาะ key ที่ระบุ จาก record ที่เพิ่ง save เข้า pid (reactive → person_info re-render)
const mergeToPid = (saved, keys) => {
  const pid = getPid()
  if (!pid || !saved) return
  keys.forEach((k) => { if (k in saved) pid[k] = saved[k] })
}
const RIGHT_KEYS  = ['inscl_main_code', 'inscl_sub_code', 'inscl_hos_main', 'inscl_hos_sub', 'inscl_hos']
const PERSON_KEYS = ['hn', 'prename', 'p_fname', 'p_lname', 'p_gender', 'birth_date', 'age', 'p_abogroup', 'p_phone', 'p_pic'].concat(RIGHT_KEYS)

// ปุ่ม: แก้ไขข้อมูลผู้รับบริการ
s.editPerson = () => {
  const pid = getPid()
  if (!pid || !pid.value) { this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning'); return }
  const form = field.getFormRef()
  form.openForm(PERSON_FORM, pid.value, null, undefined, {
    afterSaveCallback: (saved) => {
      form.subFormClose()
      mergeToPid(saved, PERSON_KEYS)   // อัปเดตชื่อ/รูป/สิทธิ ใน person_info
    },
  })
}

// ปุ่ม: ตรวจสอบสิทธิ
s.checkRight = async () => {
  const pid = getPid()
  if (!pid || !pid.value) { this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning'); return }
  const form = field.getFormRef()
  const today = field.dayjs().format('YYYY-MM-DD')
  await form.userState.runProcess(CHECK_PROC, { pid: pid.value, date: today }, (res) => {
    const existId = (res && res.data && res.data.insuranceId) || null
    form.openForm(INSURANCE_FORM, existId, pid.value, undefined, {
      afterSaveCallback: (saved) => {
        form.subFormClose()
        mergeToPid(saved, RIGHT_KEYS)   // อัปเดตสิทธิ ใน person_info
      },
    })
  })
}

// ปุ่ม: open visit
s.openVisit = () => {
  const pid = getPid()
  if (!pid || !pid.value) { this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning'); return }
  const form = field.getFormRef()
  form.openForm(VISIT_FORM, null, pid.value, undefined, {
    afterSaveCallback: () => {
      form.subFormClose()
      const editor = form.getFieldRef('visit_list') && form.getFieldRef('visit_list').getFieldEditor()
      if (editor && editor.refreshData) editor.refreshData()
    },
  })
}

options.onCardRead:
// เสียบบัตร → หาผู้ป่วยจาก CID: เจอ = เลือก pid ให้, ไม่เจอ = เปิดฟอร์มใหม่ prefill ข้อมูลบัตร
if (!ok || !data || !data.cid) {
  this.notify('อ่านบัตรไม่สำเร็จ: ' + (error || 'unknown'), 'error')
  return
}

const PERSON_FORM = '6a37d3bd4cfbfdbe257fc912'
const form = this.getFormRef()
const cid  = String(data.cid).trim()

// วันเกิดบัตรเป็น พ.ศ. ("2530-01-15") — ฟอร์มเก็บ ค.ศ. → ลบ 543
// บัตรบางใบวัน/เดือนเป็น "00" (รู้แต่ปี) → แทนด้วย "01" ให้เป็นวันที่ valid
const toADBirthDate = (th) => {
  if (!th || th.length < 10) return null
  let [y, m, d] = th.split('-')
  const yad = Number(y) - 543
  if (!yad || yad < 1900) return null
  if (!m || m === '00') m = '01'
  if (!d || d === '00') d = '01'
  return `${yad}-${m}-${d}`
}

// query PERSON จาก p_cid (เก็บเลข 13 หลักล้วน ตรงกับ cid บัตร)
const sdProvider = {
  providerId: PERSON_FORM,
  providerType: 'FORM',
  params: {},
  options: {
    fileter: { p_cid: [cid] },          // → WHERE p_cid IN (cid)
    select: ['_id', 'hn', 'p_fname', 'p_lname'],
    limit: 1,
  },
}

await form.userState.crudGetAll({ sdProvider, totalEnable: false }, (res) => {
  const found = ((res && res.data) || [])[0]

  // เจอ → เลือก pid ให้ (set {value:_id} → select ดึง record เต็ม + refField มา render person_info เอง)
  if (found && found._id) {
    form.setFieldValue('pid', { value: found._id })
    this.notify(`พบผู้ป่วย HN${found.hn || ''} ${found.p_fname || ''} ${found.p_lname || ''}`, 'success')
    return
  }

  // ไม่เจอ → เปิดฟอร์ม PERSON ใหม่ prefill จากบัตร
  const initData = {
    p_idtype: '1',                       // บัตรประชาชน
    p_cid: cid,
    p_fname: data.firstNameTH || '',
    p_lname: data.lastNameTH || '',
  }
  if (data.gender === '1' || data.gender === '2') initData.p_gender = data.gender
  const bd = toADBirthDate(data.birthDate)
  if (bd) initData.birth_date = bd

  form.openForm(PERSON_FORM, null, null, initData, {
    afterSaveCallback: (saved) => {
      form.subFormClose()
      if (saved && saved._id) form.setFieldValue('pid', { value: saved._id })  // เลือกคนที่เพิ่งสร้าง
    },
  })
})

buttons.onClick:
// อ่านค่าช่องค้นหา → ประกอบ WHERE แบบ dynamic → ยิงเข้า datagrid person_list
const form = this.getFormRef()
const val  = (name) => {
  const v = form.getFieldValue(name)
  return v == null ? '' : String(v).trim()
}

const cond   = val('cond_with') || 'or'
const groups = []
const params = {}

// เพิ่มกลุ่มเงื่อนไขเมื่อช่องมีค่า (contains match: %คำ%)
const add = (name, expr, key) => {
  const v = val(name)
  if (!v) return
  params[key] =  v + '%'
  groups.push(expr)
}

// IDs: ค้นเลข id ล้วนทุกชนิด — th13→p_cid, ppn→p_ppn, mom→p_mom_cid, เลขชั่วคราว→p_temp (prefix match ใช้ index ได้)
add('ids', '(p_cid LIKE :ids OR p_ppn LIKE :ids OR p_mom_cid LIKE :ids OR p_temp LIKE :ids)', 'ids')
add('fname',   'p_fname LIKE :fname', 'fname')
add('lname',   'p_lname LIKE :lname', 'lname')
add('r_fname', '`relate.r_fname` LIKE :rfname', 'rfname')
add('r_lname', '`relate.r_lname` LIKE :rlname', 'rlname')
// Phone: p_phone / relate.r_telecom  (OR ภายในกลุ่มเสมอ)
add('phone', '(p_phone LIKE :phone OR `relate.r_telecom` LIKE :phone)', 'phone')

// วันเกิด = exact (birth_date เก็บ YYYY-MM-DD ตรงกับ valueFormat ของช่อง bod)
const bod = val('bod')
if (bod) { params.bod = bod; groups.push('birth_date = :bod') }

if (!groups.length) {
  this.alert('กรุณากรอกเงื่อนไขค้นหาอย่างน้อย 1 ช่อง', 'warning')
  return
}

// join ทุกกลุ่มด้วย OR/AND ตาม cond_with
const where = groups.join(cond === 'and' ? ' AND ' : ' OR ')

const grid = this.getFieldRef('person_list').getFieldEditor()
if (!grid) { this.alert('ยังโหลดตารางผลลัพธ์ไม่เสร็จ ลองอีกครั้ง', 'warning'); return }
grid.dpFormData.options.where = where
grid.dpFormData.params        = params
grid.dpFormData.options.page  = 1
grid.total = 0            // บังคับ count ใหม่
grid.refreshData()

// ล้างช่องค้นหาทั้งหมด + คืน datagrid เป็นสถานะว่าง
const form = this.getFormRef()
;['ids', 'fname', 'lname', 'r_fname', 'r_lname', 'phone', 'bod'].forEach((n) => form.setFieldValue(n, null))
form.setFieldValue('cond_with', 'or')

const grid = this.getFieldRef('person_list').getFieldEditor()
if (grid) {
  grid.dpFormData.options.where = ""   // เงื่อนไขคืน 0 แถว = ตารางว่าง hn = '__NONE__'
  grid.dpFormData.params        = {}
  grid.dpFormData.options.page  = 1
  grid.total = 0
  grid.refreshData()
}

