options.onCreated:
const s = this.vueState
const field = this

// prefix flow* กันชนกับ formParams (params ชนะ state)
s.flowVisits = []
s.flowVid = ''
s.flowSteps = []
s.flowNodes = []
s.flowEdges = []
s.flowLoading = false

s.fmtDur = (m) => (m >= 60 ? Math.floor(m / 60) + 'h ' + (m % 60) + 'm' : m + 'm')
// ตัด email ออกจากชื่อหมอ
s.fmtDoc = (d) => (d || '').replace(/\S+@\S+/g, '').trim()

// เก็บ vue-flow instance ใน closure (ห้ามใส่ vueState — instance โดน reactive wrap แล้วเพี้ยน)
let flowInst = null
const fit = () => setTimeout(() => {
  if (flowInst) flowInst.fitView({ padding: 0.25, maxZoom: 1 })
}, 50)
s.flowReady = (inst) => { flowInst = inst; fit() }

const buildFlow = () => {
  s.flowNodes = s.flowSteps.map((st, i) => ({
    id: 'n' + i, type: 'station', position: { x: i * 250, y: 40 },
    sourcePosition: 'right', targetPosition: 'left',  // ★ เส้นออกขวา → เข้าซ้าย
    data: st,
  }))
  s.flowEdges = s.flowSteps.slice(1).map((st, i) => ({
    id: 'e' + i, source: 'n' + i, target: 'n' + (i + 1),
    type: 'smoothstep', animated: st.current === true, markerEnd: 'arrowclosed',
    style: st.current
      ? { stroke: 'var(--el-color-primary)', strokeWidth: 2 }
      : { stroke: 'var(--el-border-color-darker)', strokeWidth: 1.5 },
  }))
  fit()  // ★ zoom ให้พอดีหลังได้ node ใหม่
}

// โหลด flow — เรียกจาก pid.onChange / เปลี่ยน visit ใน dropdown
s.flowLoad = (vid) => {
  const pid = field.formModel.pid && field.formModel.pid.value
  if (!pid) { s.flowVisits = []; s.flowSteps = []; s.flowNodes = []; s.flowEdges = []; return }
  s.flowLoading = true
  field.getFormRef().userState.runProcess('6a5080bb6e185ae01ab5bb1b', { pid: pid, vid: vid || '' }, (res) => {
    const out = (res && res.data) || {}
    s.flowVisits = out.visits || []
    s.flowVid = out.vid || ''
    s.flowSteps = out.steps || []
    buildFlow()
    s.flowLoading = false
  }, () => { s.flowLoading = false })
}

